// Sentry配置
import * as Sentry from '@sentry/react';

Sentry.init({
  dsn: 'https://xxx@sentry.io/xxx',
  environment: process.env.NODE_ENV,
  release: process.env.npm_package_version,
  integrations: [
    Sentry.browserTracingIntegration(),
    Sentry.replayIntegration()
  ],
  tracesSampleRate: 0.1, // 10%的性能追踪
  replaysSessionSampleRate: 0.1,
  replaysOnErrorSampleRate: 1.0, // 错误时100%录制
  beforeSend(event) {
    // 过滤敏感信息
    if (event.exception) {
      const error = event.exception.values[0];
      if (error?.value?.includes('Script error')) return null;
    }
    return event;
  }
});

// 全局错误捕获
window.onerror = (msg, url, line, col, error) => {
  console.error('Global error:', { msg, url, line, col, error });
  // 上报到监控平台
};

window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled rejection:', event.reason);
});

// 资源加载错误
document.addEventListener('error', (event) => {
  if (event.target.tagName) {
    console.error('Resource error:', event.target.src || event.target.href);
  }
}, true);

// Core Web Vitals监控
import { onLCP, onFID, onCLS, onINP } from 'web-vitals';

function sendToAnalytics({ name, value, id }) {
  // 发送到监控平台
  navigator.sendBeacon('/api/vitals', JSON.stringify({ name, value, id }));
}

onLCP(sendToAnalytics);
onFID(sendToAnalytics);
onCLS(sendToAnalytics);
onINP(sendToAnalytics);

// 自定义性能埋点
function measurePerformance(name, fn) {
  const start = performance.now();
  const result = fn();
  const duration = performance.now() - start;
  console.log(`${name}: ${duration.toFixed(2)}ms`);
  return result;
}

// Source Map配置
// .sentryclirc
// [auth]
// token=xxx
// [defaults]
// org=my-org
// project=my-project

// webpack配置
module.exports = {
  devtool: 'hidden-source-map', // 生成但不暴露
};

// vite配置
export default defineConfig({
  build: {
    sourcemap: 'hidden'
  }
});
